if getattr(mibBuilder, 'version', (0, 0, 0)) > (4, 4, 0):
    if mibBuilder.loadTexts: ciscoDspMgmtMIB.setRevisionsDescriptions(('Added following OBJECT-GROUP:\n        - cdspTranscodeProfileGroup \n        - cdspMtpProfileGroup \n        - cdspConferenceProfileGroup \n        Added new compliance \n        - cdspMgmtComplianceRev12.', '1. Added cdspCardVideoPoolUtilization and\n        cdspCardVideoPoolUtilizationThreshold to cdspCardStatusTable.\n\n        2. Added cdspVideoUsageNotificationEnable and\n        cdspVideoOutOfResourceNotificationEnable to\n        cdspMIBNotificationEnables.\n\n        4. Added 2 new notifications: cdspVideoUsageNotification and\n        cdspVideoOutOfResourceNotification.\n\n        5. Deprecated cdspMgmtComplianceRev10 and added\n        cdspMgmtComplianceRev11.\n\n        7. Added cdspMgmtVideoInfoGroup and\n        cdspMgmtVideoNotificationsGroup.', '1. Added the following new OBJECT IDENTIFIERs:\n        cdspDspfarmObjects, \n        cdspDspfarmUtilObjects.\n        2. Added the following objects to cdspDspfarmObjects: \n        cdspGlobMaxConfTranscodeSess,\n        cdspGlobMaxAvailTranscodeSess.\n        3. Added cdspTranscodeProfileTable.\n        4. Added cdspMtpProfileTable.\n        5. Added the following objects to cdspDspfarmUtilObjects:\n        cdspTotAvailTranscodeSess,\n        cdspTotUnusedTranscodeSess,\n        cdspTotAvailMtpSess,\n        cdspTotUnusedMtpSess.\n        6. Added OBJECT-GROUP cdspDspfarmInfoGroup. \n        7. Deprecated MODULE-COMPLIANCE cdspMgmtComplianceRev9.\n        8. Added MODULE-COMPLIANCE cdspMgmtComplianceRev10.', 'Added cdspUtilTable to have MIB support for utilised and free\n        DSP channels corresponding to codec pools available in codec\n        template currently active on VXSM.', 'Added two values to object cdspCodecTemplateSupported to\n        support TGW2 and FMC codec templates.', '1. Added cdspVoiceModeIpIp object in cdspVoiceParamTable.\n        2. Deprecated cdspTransparentIpIp.', 'Added following objects in cdspVoiceParamTable:\n        cdspTransparentIpIp', 'Added following objects in cdspVoiceParamTable:\n        cdspVqmThreshSES   \n        Modified the following objects in cdspVoiceParamTable:\n                cdspVqmControl', 'Added following objects to cdspVoiceParamTable:\n        cdspPktLossConcealment', 'Added following objects to cdspVoiceParamTable:\n        cdspVqmControl\n        cdspRtcpXrControl\n        cdspRtcpXrTransMultiplier\n        cdspRtcpXrGminDefault\n        cdspRtcpXrExtRfactor', 'Added entPhysicalName to the OBJECTS clause of\n        cdspOperStateNotification.', "Added object cdspEnableOperStateNotification\n        to enable cdspOperStateNotification.\n        Added cdspOperStateNotification to reflect\n        cdspOperState in 'normal' or 'shutdown' state.", 'Added object cdspCodecTemplateSupported to\n        cdspCardStatusTable.', 'Added object cdspRtcpTimerControl to\n        cdspVoiceParamTable.', 'Added object cdspDspNum to cdspStatusTable.', 'Changing the DESCRIPTION of\n        cdspMIBCardStateNotification \n        to notify Manager whenever\n        cdspCardState enters normal.', '(1) Added following objects to cdspCardStatusTable:\n        cdspTotalDsp\n        cdspFailedDsp\n        cdspCongestedDsp  \n        cdspNormalDsp       \n        cdspNx64Dsp\n        cdspDspSwitchOverThreshold\n        (2) Added cdspVoiceParamTable \n        (3) Added following objects to cdspStatusTable:\n        cdspSigBearerChannelSplit\n        cdspNumCongestionOccurrence\n        (4) Added following enumerations to cdspOperState:\n        congested (3)\n        failed    (4)\n        (5) Added cdspStatusXTable', "Fix typo in the DESCRIPTION clause of\n        cdspMIBEnableCardStatusNotification object;\n        change 'cdspFatalNotification' to \n        'cdspMIBCardStateNotification'.", 'Add new objects to support channelized DSP features.',))
