cdspRtcpControl = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 9, 86, 1, 4, 1, 1, 2), TruthValue().clone('true')).setMaxAccess("readwrite")
if mibBuilder.loadTexts: cdspRtcpControl.setReference('Appendix A.7 of RFC1889')
